async function renderPreview(){if(!STATE.fileBytes||!STATE.ready)return;const token=++STATE.renderToken,number=Number($('previewPage').value)||1;setStatus(`Вырезание карточек и сборка страницы ${number}…`);try{await ensureThemeAssets(number-1);if(token!==STATE.renderToken)return;const original=await renderSource(number,previewScale());if(token!==STATE.renderToken)return;const layers=createLayers(original,number-1);const final=document.createElement('canvas');final.width=original.width;final.height=original.height;const ctx=final.getContext('2d');ctx.drawImage(layers.below,0,0);ctx.drawImage(original,0,0);ctx.drawImage(layers.above,0,0);const shell=$('sheetShell');shell.innerHTML='';shell.append(final);setStatus(`Предпросмотр готов в повышенном качестве: ${activeRaceTheme().label} + ${activeClassTheme().label}, стр. ${number}.`)}catch(error){console.error(error);setStatus('Ошибка предпросмотра: '+error.message,true)}}
const UNIVERSAL_JPEG_QUALITY=.95;
function composeOpaquePage(original,pageIndex){const composed=composeExactPage(original,pageIndex),flat=document.createElement('canvas');flat.width=original.width;flat.height=original.height;const ctx=flat.getContext('2d',{alpha:false});ctx.fillStyle='#fff';ctx.fillRect(0,0,flat.width,flat.height);ctx.drawImage(original,0,0);ctx.drawImage(composed,0,0);composed.width=composed.height=1;return flat}
async function universalJpgBytes(canvas){const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('Не удалось создать совместимую JPEG-страницу')),'image/jpeg',UNIVERSAL_JPEG_QUALITY));return new Uint8Array(await blob.arrayBuffer())}
function startDesktopDownload(url,name){const a=document.createElement('a');a.href=url;a.download=name;a.rel='noopener';document.body.append(a);a.click();a.remove()}
async function exportPdf(){if(!STATE.fileBytes||!STATE.ready||STATE.exporting)return;STATE.exporting=true;clearPreparedDownload();setExportButtonsDisabled(true);const scale=qualityScale(),dpi=Math.round(scale*72);setStatus('Подготовка универсального PDF…');try{const sourceBytes=STATE.fileBytes.slice(0),out=await PDFLib.PDFDocument.load(sourceBytes,{updateMetadata:false}),originalCount=out.getPageCount(),keepCount=await trimmedSourcePageCount(originalCount),removed=originalCount-keepCount;for(let i=originalCount-1;i>=keepCount;i--)out.removePage(i);const pages=out.getPages().slice(0,keepCount);for(let i=0;i<pages.length;i++){setStatus(`Композиция ${i+1}/${pages.length}: ${dpi} DPI · универсальная страница…`);await ensureThemeAssets(i);const original=await renderSource(i+1,scale),flat=composeOpaquePage(original,i),page=pages[i],width=page.getWidth(),height=page.getHeight(),jpeg=await universalJpgBytes(flat),image=await out.embedJpg(jpeg);page.drawImage(image,{x:0,y:0,width,height});original.width=original.height=1;flat.width=flat.height=1;await new Promise(resolve=>setTimeout(resolve,32))}setStatus('Сохранение совместимого PDF…');out.setProducer('MasterM4C9 Universal PDF');const bytes=await out.save({useObjectStreams:false,addDefaultPage:false}),base=STATE.fileName.replace(/\.pdf$/i,'')||'LSS',race=activeRaceTheme().label,cls=activeClassTheme().label,filename=`${base} - ${race} + ${cls} - MasterM4C9.pdf`,prepared=prepareDownload(bytes,filename);if(!isMobileDevice())startDesktopDownload(prepared.url,filename);setStatus(`Готово: ${filename}. ${dpi} DPI, единый совместимый слой JPEG ${Math.round(UNIVERSAL_JPEG_QUALITY*100)}%.${removed?` Удалено пустых листов в конце: ${removed}.`:''} Нажмите «Скачать готовый PDF» ниже.`)}catch(error){console.error(error);setStatus('Ошибка экспорта: '+error.message,true)}finally{STATE.exporting=false;setExportButtonsDisabled(!STATE.fileBytes)}}
async function inspectFile(file){clearPreparedDownload();if(STATE.pdfDoc){await STATE.pdfDoc.destroy();STATE.pdfDoc=null}STATE.fileBytes=new Uint8Array(await file.arrayBuffer());STATE.fileName=file.name;const task=STATE.pdfjs.getDocument({data:STATE.fileBytes.slice(0)});const doc=await task.promise;STATE.pdfDoc=doc;STATE.pageCount=doc.numPages;const first=await doc.getPage(1),box=first.getViewport({scale:1});first.cleanup();$('fileInfo').textContent=`${file.name} · ${doc.numPages} стр. · ${Math.round(box.width)}×${Math.round(box.height)} pt`;const sel=$('previewPage');sel.innerHTML='';for(let i=1;i<=doc.numPages;i++){const opt=document.createElement('option');opt.value=i;opt.textContent=`${i} · ${pageConfig(i-1).name}`;sel.append(opt)}sel.disabled=false;$('previewBtn').disabled=false;setExportButtonsDisabled(false);buildAudit();await renderPreview()}
function normalizeRaceSearch(value){return String(value||'').toLocaleLowerCase('ru-RU').replace(/ё/g,'е').replace(/й/g,'и').replace(/[^a-zа-я0-9]+/gi,'')}
function sortSelectOptions(id){const select=$(id);if(!select?.options||typeof select.append!=='function')return;const value=select.value,options=[...select.options].sort((a,b)=>a.textContent.localeCompare(b.textContent,'ru',{sensitivity:'base'}));for(const option of options)select.append(option);select.value=value}
function filterRaceOptions(){const query=normalizeRaceSearch($('raceSearch').value),options=[...$('race').options];let shown=0;for(const option of options){const visible=!query||normalizeRaceSearch(`${option.textContent} ${option.value}`).includes(query);option.hidden=!visible;option.disabled=!visible;if(visible)shown++}$('raceCount').textContent=query?`Найдено: ${shown} из ${options.length}`:`${options.length} рас`}
async function chooseFirstRaceMatch(event){if(event.key==='Escape'){$('raceSearch').value='';filterRaceOptions();return}if(event.key!=='Enter')return;event.preventDefault();const option=[...$('race').options].find(item=>!item.hidden&&!item.disabled);if(!option)return;$('race').value=option.value;$('raceSearch').value='';filterRaceOptions();await changeTheme()}
async function changeTheme(){const raceId=$('race').value;if(!raceId)return;clearPreparedDownload();STATE.raceId=raceId;STATE.classId=$('class').value;updateThemeInfo();if(STATE.fileBytes&&STATE.ready)await renderPreview();else setStatus(`Выбрана тема: ${activeRaceTheme().label} + ${activeClassTheme().label}. Загрузите PDF LSS.`)}
$('pdf').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(!STATE.ready){setStatus('PDF выбран. Завершаю запуск локального движка…');await STATE.bootPromise}if(!STATE.ready)throw new Error('PDF-движок не запущен');setStatus('Чтение PDF и проверка геометрии…');await inspectFile(file)}catch(error){console.error(error);setStatus('Этот файл не удалось открыть как PDF: '+error.message,true)}});
$('raceSearch').addEventListener('input',filterRaceOptions);$('raceSearch').addEventListener('keydown',chooseFirstRaceMatch);$('race').addEventListener('change',changeTheme);$('class').addEventListener('change',changeTheme);$('previewBtn').addEventListener('click',renderPreview);$('previewPage').addEventListener('change',renderPreview);$('export').addEventListener('click',exportPdf);$('exportMobile').addEventListener('click',exportPdf);$('downloadResult').addEventListener('click',openPreparedDownload);for(const id of ['background','frames','brand'])$(id).addEventListener('change',async()=>{clearPreparedDownload();if(STATE.fileBytes&&STATE.ready)await renderPreview()});$('reset').addEventListener('click',async()=>{clearPreparedDownload();if(STATE.pdfDoc){await STATE.pdfDoc.destroy();STATE.pdfDoc=null}STATE.fileBytes=null;STATE.fileName='';STATE.pageCount=0;STATE.raceId='elf';STATE.classId='druid';$('pdf').value='';$('race').value='elf';$('class').value='druid';$('raceSearch').value='';for(const id of ['background','frames','brand'])$(id).checked=true;$('fileInfo').textContent='Файл ещё не выбран';$('previewPage').innerHTML='';$('previewPage').disabled=true;$('previewBtn').disabled=true;setExportButtonsDisabled(true);$('sheetShell').innerHTML='<div class="empty"><div class="rune">ᚫ</div><b>Загрузите лист LSS</b><p>Выберите расу и класс — оформление появится здесь.</p></div>';filterRaceOptions();updateThemeInfo();buildAudit();setStatus('Готово к работе. Выберите PDF LSS.')});
sortSelectOptions('race');sortSelectOptions('class');filterRaceOptions();updateThemeInfo();buildAudit();STATE.bootPromise=boot();
